arguments.command:
python3 -c "
import json, re
from collections import Counter
# For collapsed steps (>=16) vs early steps (<=5), characterize response endings
def classify(resp):
    has_box = '\\\\boxed' in resp
    return 'boxed' if has_box else 'no_box'
buckets = {'early': [], 'mid': [], 'late': []}
with open('observed_run/rewards.jsonl') as f:
    for line in f:
        d = json.loads(line)
        step = d['trainer_step']
        c = classify(d['response'])
        if step <= 5: buckets['early'].append(c)
        elif step <= 15: buckets['mid'].append(c)
        else: buckets['late'].append(c)
for k, v in buckets.items():
    print(k, Counter(v), 'total', len(v))
"

